(function(){function t(e){var t=e.getAttribute("data-bs-target");if(!t)return;var n=document.querySelector(t);if(!n)return;document.querySelectorAll('.nav-tabs .nav-link').forEach(function(e){e.classList.remove('active')});document.querySelectorAll('.tab-pane').forEach(function(e){e.classList.remove('active','show')});e.classList.add('active');n.classList.add('active','show')}document.addEventListener('click',function(e){var n=e.target.closest('[data-bs-toggle="tab"]');n&&(e.preventDefault(),t(n))})})();